import json, os, re
from pathlib import Path
from bs4 import BeautifulSoup

base = Path(os.environ['TMPDIR'])

def clean(x):
    return ' '.join(x.get_text(' ', strip=True).split())

def rows(kind):
    soup=BeautifulSoup((base/f'iftm_{kind}.html').read_text(errors='replace'),'html.parser')
    return [[clean(c) for c in tr.find_all(['th','td'])] for tr in soup.find('table').find_all('tr')]

