def mp(key, relation='direct discipline mapping', confidence='high', status='reviewed_against_local_tree'):
    i,s,b=N[key]
    return {'career_node_id':i,'career_node_slug':s,'career_breadcrumb':b,'relation':relation,'confidence':confidence,'mapping_status':status}

def near(key, relation='nearest parent mapping', confidence='medium'):
    return mp(key,relation,confidence,'reviewed_with_career_tree_label_issue')

def map_diploma(name):
    l=name.lower()
    if 'hotel' in l: return near('hotel','closest specialization mapping','medium')
    if 'd.pharm' in l: return near('bpharm','closest programme-family mapping','medium')
    if 'civil' in l: return near('diploma_civil','closest specialization mapping','medium')
    if 'electrical' in l: return near('diploma_elec','closest specialization mapping','medium')
    if 'mechanical' in l: return near('diploma_mech','closest specialization mapping','medium')
    return near('diploma','nearest parent mapping','medium')

def map_ug(name):
    l=name.lower()
    if l.startswith('bba'): return mp('bba')
    if l.startswith('b.com'): return mp('bcom')
    if 'hotel' in l: return mp('hotel')
    if l.startswith('b.pharm'): return mp('bpharm')
    if 'home science' in l and l.startswith('b.sc'): return near('science_common','nearest parent mapping','low')
    if 'p/c/m/z/b' in l: return near('science_maths','nearest parent mapping','low')
    if 'civil engineering' in l: return mp('btech_civil')
    if 'mechanical engineering' in l: return mp('btech_mech')
    if 'electrical engineering' in l: return mp('btech_elec')
    if 'electronics & communication' in l: return mp('btech_ece')
    if 'history' in l: return mp('ba_history')
    if l == 'ba (hons. with research) home science': return near('science_common','nearest parent mapping','low')
    if l == 'ba (hons. with research) education': return mp('ba_education')
    if 'ba-b.ed' in l or 'b.sc.-b.ed' in l: return near('ba_education','closest specialization mapping','medium')
    if l == 'b.ed.': return mp('ba_education')
    if 'journalism' in l: return near('bjmc','closest specialization mapping','medium')
    if 'library' in l: return near('social_root','nearest parent mapping','low')
    if 'english' in l: return mp('ba_english')
    if 'hindi' in l: return mp('ba_hindi')
    if 'economics' in l: return mp('ba_econ')
    if 'geography' in l: return near('social_root','nearest parent mapping','low')
    if 'sociology' in l: return mp('ba_sociology')
    if 'political science' in l: return mp('ba_polsci')
    if 'sanskrit' in l: return near('languages_root','nearest parent mapping','low')
    if 'b.tech (biotechnology)' in l: return mp('btech_biotech')
    if 'food technology' in l: return mp('bsc_food')
    if 'biotechnology' in l: return mp('bsc_bio')
    if 'microbiology' in l: return mp('bsc_micro')
    if l == 'll.b': return near('law_root','nearest parent mapping','medium')
    if 'b.b.a. ll.b' in l: return mp('bba_llb')
    if 'b.a. ll.b' in l: return mp('ba_llb')
    if 'computer sc.' in l: return mp('btech_cs')
    if 'artificial intelligence' in l: return mp('btech_ai')
    if l.startswith('bca'): return mp('bca')
    if 'agriculture engineering' in l: return near('agri','closest specialization mapping','medium')
    if 'b.sc. (hons.) ag' in l: return mp('agri')
    raise ValueError(('UG unmapped',name))

def map_pg(name):
    l=name.lower()
    if l == 'mba': return mp('mba')
    if l == 'm.com.': return mp('mcom')
    if 'hotel management' in l: return mp('hotel')
    if l.startswith('m.pharm'): return mp('pharma_research')
    if 'botany' in l or 'zoology' in l: return near('science_bio','closest specialization mapping','medium')
    if 'home science' in l: return near('science_common','nearest parent mapping','low')
    if 'physics' in l: return mp('bsc_physics')
    if 'chemistry' in l: return mp('bsc_chem')
    if 'maths' in l: return mp('bsc_maths')
    if 'civil engineering' in l: return mp('btech_civil')
    if 'mechanical engineering' in l: return mp('btech_mech')
    if 'electrical engineering' in l: return mp('btech_elec')
    if 'electronics & communication' in l: return mp('btech_ece')
    if l == 'm.ed.': return mp('ba_education')
    if 'ma (education)' in l: return mp('ba_education')
    if 'ma (journalism)' in l: return near('bjmc','closest specialization mapping','medium')
    if 'm.lib.' in l: return near('social_root','nearest parent mapping','low')
    if 'social work' in l: return near('ba_sociology','closest specialization mapping','medium')
    if 'ma (english)' in l: return mp('ba_english')
    if 'ma (hindi)' in l: return mp('ba_hindi')
    if 'ma (economics)' in l: return mp('ba_econ')
    if 'ma (geography)' in l: return near('social_root','nearest parent mapping','low')
    if 'ma (sociology)' in l: return mp('ba_sociology')
    if 'm.sc. (biotechnology)' in l: return mp('msc_biotech')
    if 'm.tech. (biotechnology)' in l: return mp('btech_biotech')
    if 'micro biology' in l: return mp('msc_micro')
    if 'food technology' in l: return mp('bsc_food')
    if l == 'llm': return near('law_root','nearest parent mapping','medium')
    if 'computer sc.' in l: return mp('btech_cs')
    if l == 'mca': return mp('mca')
    if any(x in l for x in ['soil & water','agronomy','horticulture','farm machinery','process & food','genetics & plant breeding']): return mp('agri')
    raise ValueError(('PG unmapped',name))

def map_phd(spec):
    l=spec.lower()
    if l=='management': return near('management_root','nearest parent mapping','medium')
    if l=='commerce': return near('accounting_root','nearest parent mapping','medium')
    if l=='pharmacy': return mp('pharma_research')
    if l=='home science': return near('science_common','nearest parent mapping','low')
    if l in ('botany','zoology'): return near('science_bio','closest specialization mapping','medium')
    if l=='physics': return mp('bsc_physics')
    if l=='chemistry': return mp('bsc_chem')
    if l=='maths': return mp('bsc_maths')
    if l=='civil engineering': return mp('btech_civil')
    if l=='electronics & communication engineering': return mp('btech_ece')
    if l=='mechanical engineering': return mp('btech_mech')
    if l=='electrical engineering': return mp('btech_elec')
    if l=='education': return mp('ba_education')
    if l=='journalism & mass communication': return near('bjmc','closest specialization mapping','medium')
    if l=='library science': return near('social_root','nearest parent mapping','low')
    if l=='english': return mp('ba_english')
    if l=='hindi': return mp('ba_hindi')
    if l=='economics': return mp('ba_econ')
    if l=='geography': return near('social_root','nearest parent mapping','low')
    if l=='sociology': return mp('ba_sociology')
    if l=='biotechnology': return mp('btech_biotech')
    if l=='law': return near('law_root','nearest parent mapping','medium')
    if l=='computer science & engineering': return mp('btech_cs')
    if l=='computer science & applications': return mp('bca')
    if 'agriculture' in l: return mp('agri')
    raise ValueError(('PhD unmapped',spec))

courses=[]
# Diploma
for idx,c in enumerate(rows('diploma')[1:],1):
    name,elig,dur = c[0],c[1],c[4]
    courses.append({'course_id':f'diploma-{idx:02d}','name':name,'level':'diploma','credential':'Diploma','specialization':None,'duration':dur,'mode':'not_stated','eligibility':elig,'official_course_url':'https://www.iftmuniversity.ac.in/iftmuniversity/diploma.php','verification_status':'verified','career_path_mappings':[map_diploma(name)],'mapping_gap':None})
# UG
for idx,c in enumerate(rows('ug')[1:],1):
    if len(c)>=7: name,elig,dur=c[1],c[2],c[5]
    else: name,elig,dur=c[0],c[1],c[4]
    courses.append({'course_id':f'ug-{idx:02d}','name':name,'level':'undergraduate','credential':\"Bachelor's degree\",'specialization':None,'duration':dur,'mode':'not_stated','eligibility':elig,'official_course_url':'https://www.iftmuniversity.ac.in/iftmuniversity/ug.php','verification_status':'verified','career_path_mappings':[map_ug(name)],'mapping_gap':None})
# PG
for idx,c in enumerate(rows('pg')[1:],1):
    if len(c)>=7: name,elig,dur=c[1],c[2],c[5]
    else: name,elig,dur=c[0],c[1],c[4]
    courses.append({'course_id':f'pg-{idx:02d}','name':name,'level':'postgraduate','credential':\"Master's degree\",'specialization':None,'duration':dur,'mode':'not_stated','eligibility':elig,'official_course_url':'https://www.iftmuniversity.ac.in/iftmuniversity/pg.php','verification_status':'verified','career_path_mappings':[map_pg(name)],'mapping_gap':None})
# PhD
for idx,c in enumerate(rows('doctor')[1:],1):
    spec,elig,dur=c[0],c[1],c[5] if len(c)>=7 else c[4]
    courses.append({'course_id':f'phd-{idx:02d}','name':'Ph.D.','level':'doctoral','credential':'Doctorate','specialization':spec,'duration':dur,'mode':'not_stated','eligibility':elig,'official_course_url':'https://www.iftmuniversity.ac.in/iftmuniversity/doctor.php','verification_status':'verified','career_path_mappings':[map_phd(spec)],'mapping_gap':None})

